package com.example.yuejie;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.accessibility.*;import org.json.*;import java.io.*;import java.util.*;
/** Observe the installed reference through public UI; no hooks or private app changes. */
public final class ReferenceCapture extends DeviceChecks {
 boolean click(String text)throws Exception{AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root==null)return false;for(AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(text)){if(!text.contentEquals(node.getText()))continue;Rect r=new Rect();node.getBoundsInScreen(r);if(!node.isVisibleToUser()||r.centerY()<0||r.centerY()>=1920||r.centerX()<0||r.centerX()>=1080)continue;swipe(r.centerX(),r.centerY(),r.centerX(),r.centerY(),30);SystemClock.sleep(500);return true;}return false;}
 public void onStart(){output=new File(getTargetContext().getFilesDir(),"reference-turn-evidence");output.mkdirs();Bundle result=new Bundle();try{launchMain();Intent launch=getTargetContext().getPackageManager().getLaunchIntentForPackage("com.dragon.read");launch.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);getTargetContext().startActivity(launch);SystemClock.sleep(2000);if(!click("设置")){swipe(540,900,540,900,30);SystemClock.sleep(500);assertTrue(click("设置"),"reference reader settings");}String label=args.getString("label","无动画");shot("settings-"+label);assertTrue(click(label),"reference mode "+label);swipe(540,350,540,350,30);SystemClock.sleep(500);shot("normal-"+label);for(float y:new float[]{400,960,1450}){swipe(918,y,180,y,700);SystemClock.sleep(1000);swipe(180,y,918,y,700);SystemClock.sleep(1000);}swipe(900,1000,820,1000,700);SystemClock.sleep(1000);swipe(900,1000,650,1000,100);SystemClock.sleep(1000);swipe(180,1000,430,1000,100);SystemClock.sleep(1000);swipe(900,1000,900,1000,30);SystemClock.sleep(1000);swipe(180,1000,180,1000,30);SystemClock.sleep(1000);shot("after-"+label);result.putString("stream","PASS reference "+label);}catch(Throwable e){result.putString("stream","FAIL "+android.util.Log.getStackTraceString(e));try{shot("failure");}catch(Exception ignored){}}finish(Activity.RESULT_OK,result);}
}
